def list_skips():
    results = {
        'dir_sys': [],
        'constants': {},
    }
    for name in dir():
        if name.startswith('_'):
            continue
        obj = eval(name)
        if inspect.isclass(obj) and not inspect.ismodule(obj):
            results['dir_sys'].append(name)
        if inspect.isfunction(obj):
            results['dir_sys'].append(name)
    return results

